package com.example.starter.race.domain;

/**
 * 赛事状态：OPEN-开放可写；SEALED-已封榜，只读。
 */
public enum RaceStatus {
    OPEN,
    SEALED
}

package com.example.starter.race.domain;

/**
 * 处罚类型：ADD_TIME-加时处罚（带毫秒时长）；DISQUALIFY-取消资格（不带时长）。
 */
public enum PenaltyType {
    ADD_TIME,
    DISQUALIFY
}

package com.example.starter.race.domain;

/**
 * 选手成绩状态：RANKED-正常参与排名；UNTIMED-计时缺失不排名；DISQUALIFIED-存在生效取消资格处罚不排名。
 */
public enum EntryStatus {
    RANKED,
    UNTIMED,
    DISQUALIFIED
}

package com.example.starter.race.domain;

/**
 * 单个选手的成绩条目。
 *
 * @param bib           参赛号
 * @param rank          名次，从1开始；并列同名次且跳号（1、1、3）；UNTIMED/DISQUALIFIED 为 null
 * @param status        成绩状态
 * @param finishTimeMs  原始完赛耗时（毫秒）；计时缺失为 null
 * @param penaltyMs     全部未撤销加时处罚的合计毫秒数；无加时为 0
 * @param totalTimeMs   总耗时=原始完赛耗时+生效加时（毫秒）；未排名时为 null
 */
public record ResultEntry(
        String bib,
        Integer rank,
        EntryStatus status,
        Long finishTimeMs,
        long penaltyMs,
        Long totalTimeMs
) {
}

package com.example.starter.race.domain;

import java.util.List;

/**
 * 一份完整成绩榜：即时成绩或封榜只读快照。
 *
 * @param raceId   赛事ID
 * @param version  计算该榜单时的赛事版本号
 * @param status   赛事状态
 * @param sealedAt 封榜时间（Unix 毫秒时间戳）；未封榜为 null
 * @param entries  按展示顺序排列的成绩条目（名次顺序，并列按参赛号字典序，未排名按参赛号字典序）
 */
public record Standing(
        String raceId,
        int version,
        RaceStatus status,
        Long sealedAt,
        List<ResultEntry> entries
) {
}

package com.example.starter.race.domain;

/**
 * 成绩排名纯逻辑：依据选手原始耗时与处罚列表计算榜单，不涉及数据库与时间。
 */
public final class ResultCalculator {

    private ResultCalculator() {
    }

    /**
     * 计算即时成绩。
     *
     * @param runnerView 全部选手视图（参赛号、原始完赛耗时）
     * @param penalties  全部处罚（含已撤销）
     * @return 按展示顺序排列的成绩条目
     */
    public static java.util.List<ResultEntry> compute(
            java.util.List<? extends RunnerView> runnerView,
            java.util.List<? extends PenaltyView> penalties) {
        throw new UnsupportedOperationException("骨架待实现");
    }

    /** 选手视图：参赛号与原始完赛耗时（null 表示计时缺失）。 */
    public interface RunnerView {
        String bib();

        Long finishTimeMs();
    }

    /** 处罚视图。 */
    public interface PenaltyView {
        String bib();

        PenaltyType type();

        Long amountMs();

        boolean revoked();
    }
}

