package com.example.starter.race.persistence;

import com.example.starter.race.domain.RaceStatus;

/**
 * race 表行记录。
 *
 * @param raceId    赛事ID，全局唯一
 * @param version   版本号，从1开始
 * @param status    赛事状态
 * @param createdAt 创建时间，Unix毫秒时间戳
 */
public record RaceRow(String raceId, int version, RaceStatus status, long createdAt) {
}

package com.example.starter.race.persistence;

/**
 * runner 表行记录。
 *
 * @param id           自增主键
 * @param raceId       所属赛事ID
 * @param bib          参赛号，赛事内唯一
 * @param finishTimeMs 原始完赛耗时（毫秒，1~86400000）；null 表示计时缺失
 * @param createdAt    登记时间，Unix毫秒时间戳
 * @param updatedAt    最近一次计时修订时间，Unix毫秒时间戳
 */
public record RunnerRow(
        long id,
        String raceId,
        String bib,
        Long finishTimeMs,
        long createdAt,
        long updatedAt
) {
}

package com.example.starter.race.persistence;

import java.util.List;

/**
 * result_snapshot 头表与其条目合成的封榜快照。
 *
 * @param raceId  赛事ID
 * @param version 封榜时的版本号
 * @param sealedAt 封榜时间，Unix毫秒时间戳
 * @param entries 按展示顺序排列的快照条目
 */
public record SnapshotRow(String raceId, int version, long sealedAt, List<SnapshotEntryRow> entries) {
}

package com.example.starter.race.persistence;

/**
 * idempotency_record 表行记录：成功写请求的原响应，供同键重放。
 *
 * @param requestId      全局唯一请求ID
 * @param operation      操作类型
 * @param requestDigest  请求参数规范化摘要（SHA-256，十六进制）
 * @param responseStatus 原成功响应HTTP状态码
 * @param responseBody   原成功响应体JSON
 * @param createdAt      首次成功提交时间，Unix毫秒时间戳
 */
public record IdempotencyRow(
        String requestId,
        String operation,
        String requestDigest,
        int responseStatus,
        String responseBody,
        long createdAt
) {
}

